challenge_result.network_analysis:
{
  "summary": "A bidirectional drop to zero in UPF N3 data-plane throughput indicates a severing of the user plane, which starves the downstream IMS chain of SIP REGISTERs and causes the uniform rate halving observed across all CSCFs.",
  "layer_status": {
    "core": {
      "rating": "red",
      "evidence": [
        "normalized.upf.gtp_indatapktn3upf_per_ue dropped to 0.00",
        "normalized.upf.gtp_outdatapktn3upf_per_ue dropped to 0.00",
        "normalized.smf.bearers_per_ue shifted to 2.00 (default no-call state)"
      ],
      "note": "UPF is receiving and sending zero data plane traffic despite UEs being attached."
    },
    "ims": {
      "rating": "yellow",
      "evidence": [
        "normalized.pcscf.core:rcv_requests_register_per_ue dropped to 0.03",
        "normalized.icscf.core:rcv_requests_register_per_ue dropped to 0.03",
        "normalized.scscf.core:rcv_requests_register_per_ue dropped to 0.03"
      ],
      "note": "All CSCFs show a 50% drop in received REGISTER rates without SIP errors; per L09 and L15, this is a downstream consequence of upstream starvation."
    },
    "ran": {
      "rating": "yellow",
      "evidence": [
        "core.amf.ran_ue = 2 (UEs are attached)"
      ],
      "note": "gNB is active but could be failing to forward user-plane traffic to the UPF on N3."
    },
    "infrastructure": {
      "rating": "green",
      "evidence": [
        "get_network_status confirms all containers running",
        "measure_rtt shows 0% loss to dns and smf"
      ],
      "note": "Core infrastructure components are responsive."
    }
  },
  "hypotheses": [
    {
      "id": "h1",
      "statement": "UPF is the source of the bidirectional N3 data plane drop, preventing SIP REGISTER packets from traversing the user plane to reach the IMS signaling chain.",
      "primary_suspect_nf": "upf",
      "supporting_events": [],
      "explanatory_fit": 0.9,
      "falsification_probes": [
        "Run measure_rtt(nr_gnb, upf) and measure_rtt(upf, smf) to triangulate if packet loss is isolated to the UPF network stack.",
        "Check UPF container logs and interface qdisc drop counters for internal data-plane faults."
      ],
      "specificity": "specific"
    },
    {
      "id": "h2",
      "statement": "gNB is the source of the N3 data plane drop, failing to forward user-plane traffic over the N3 link to UPF.",
      "primary_suspect_nf": "nr_gnb",
      "supporting_events": [],
      "explanatory_fit": 0.8,
      "falsification_probes": [
        "Run measure_rtt(nr_gnb, upf) and measure_rtt(nr_gnb, amf) to triangulate if packet loss originates specifically at the gNB stack.",
        "Check gNB logs for radio link failures or N3 GTP-U encapsulation errors."
      ],
      "specificity": "specific"
    },
    {
      "id": "h3",
      "statement": "P-CSCF is the source of the SIP REGISTER rate drop due to an inbound partition, while the UPF N3 drop flags are artifacts of bucket (0,1) baseline pollution as per L03.",
      "primary_suspect_nf": "pcscf",
      "supporting_events": [],
      "explanatory_fit": 0.6,
      "falsification_probes": [
        "Run measure_rtt(upf, pcscf) to verify if the Gm path is lossy specifically at P-CSCF.",
        "Inspect P-CSCF logs for internal processing errors that could silently drop inbound REGISTERs."
      ],
      "specificity": "moderate"
    }
  ]
}

challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "UPF is the source of the bidirectional N3 data plane drop, preventing SIP REGISTER packets from traversing the user plane to reach the IMS signaling chain.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "nr_gnb -> upf_ip",
          "expected_if_hypothesis_holds": "Packet loss > 0% or RTT > baseline.",
          "falsifying_observation": "0% packet loss and normal RTT.",
          "conflates_with": [
            "network path between gNB and UPF",
            "gNB networking interfaces"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "upf -> smf_ip",
          "expected_if_hypothesis_holds": "Packet loss > 0% or RTT > baseline, isolating the UPF as the common source of the drop across its interfaces.",
          "falsifying_observation": "0% packet loss and normal RTT. The deviation in the first probe is attributable to the gNB or the gNB-UPF path, not the UPF.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Returns rate-windowed UPF in/out pps over the probe's window to read upf.gtp_indatapktn3upf_per_ue",
          "expected_if_hypothesis_holds": "Data plane dead on uplink, UPF receiving no packets from gNB (value is zero or significantly dropped).",
          "falsifying_observation": "Value within typical range (0.0, 10.0), indicating traffic is successfully arriving at UPF.",
          "conflates_with": []
        }
      ],
      "notes": "Uses KB-authored upf.gtp_indatapktn3upf_per_ue to verify N3 drop and measure_rtt compositional partner probes to isolate UPF network stack from gNB or path issues."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "gNB is the source of the N3 data plane drop, failing to forward user-plane traffic over the N3 link to UPF.",
      "primary_suspect_nf": "nr_gnb",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "nr_gnb -> upf_ip",
          "expected_if_hypothesis_holds": "Packet loss > 0% or RTT > baseline.",
          "falsifying_observation": "0% packet loss and normal RTT.",
          "conflates_with": [
            "network path between gNB and UPF",
            "UPF networking interfaces"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "nr_gnb -> amf_ip",
          "expected_if_hypothesis_holds": "Packet loss > 0% or RTT > baseline, isolating the gNB as the common source of the drop.",
          "falsifying_observation": "0% packet loss and normal RTT. The deviation in the first probe is attributable to the UPF or the gNB-UPF path, not the gNB.",
          "conflates_with": []
        },
        {
          "tool": "get_network_status",
          "args_hint": "Check nr_gnb container status",
          "expected_if_hypothesis_holds": "Container is exited or repeatedly restarting.",
          "falsifying_observation": "Container is running stably with no restarts.",
          "conflates_with": []
        }
      ],
      "notes": "Uses cross-interface triangulation for gNB (to UPF vs AMF) to confirm if the packet drop is isolated to gNB."
    },
    {
      "hypothesis_id": "h3",
      "hypothesis_statement": "P-CSCF is the source of the SIP REGISTER rate drop due to an inbound partition, while the UPF N3 drop flags are artifacts of bucket (0,1) baseline pollution as per L03.",
      "primary_suspect_nf": "pcscf",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "upf -> pcscf_ip",
          "expected_if_hypothesis_holds": "Packet loss > 0% or RTT > baseline on the Gm interface path.",
          "falsifying_observation": "0% packet loss and normal RTT.",
          "conflates_with": [
            "network path between UPF and P-CSCF",
            "UPF networking interfaces"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "pcscf -> icscf_ip",
          "expected_if_hypothesis_holds": "Packet loss > 0% or RTT > baseline, isolating the P-CSCF as the common source of the partition.",
          "falsifying_observation": "0% packet loss and normal RTT. The deviation in the first probe is attributable to the UPF or the UPF-PCSCF path, not the P-CSCF.",
          "conflates_with": []
        },
        {
          "tool": "run_kamcmd",
          "args_hint": "run_kamcmd('pcscf', 'stats.fetch script:register_time') to read pcscf.avg_register_time_ms",
          "expected_if_hypothesis_holds": "Ratio snapshots to 0 (numerator did not advance while denominator did) or metric is completely absent, indicating stall or no arrivals.",
          "falsifying_observation": "Value within typical range (150.0, 350.0), indicating REGISTERs are arriving and completing.",
          "conflates_with": []
        }
      ],
      "notes": "Validates inbound partition at P-CSCF using RTT across two interfaces (Gm vs Mw) to localize the fault to P-CSCF. Uses KB candidate run_kamcmd script:register_time to confirm stall."
    }
  ]
}
